import json

class Solution:
    def differByOne(self, dict):
        children = [{}]
        terminal = [False]

        for word in dict:
            node = 0
            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    terminal.append(False)
                node = nxt
            terminal[node] = True

        for word in dict:
            states = {(0, False)}
            for ch in word:
                next_states = set()
                for node, used in states:
                    if used:
                        nxt = children[node].get(ch)
                        if nxt is not None:
                            next_states.add((nxt, True))
                    else:
                        nxt = children[node].get(ch)
                        if nxt is not None:
                            next_states.add((nxt, False))
                        for other, child in children[node].items():
                            if other != ch:
                                next_states.add((child, True))
                states = next_states
                if not states:
                    break

            if any(used and terminal[node] for node, used in states):
                return True
        return False

