import java.io.*;
import java.util.*;

class Solution {
    public boolean differByOne(String[] dict) {
        int total = 0;
        for (String word : dict) total += word.length();
        int[] child = new int[(total + 1) * 26];
        boolean[] terminal = new boolean[total + 1];
        int nodeCount = 1;

        for (String word : dict) {
            int node = 0;
            for (int i = 0; i < word.length(); i++) {
                int c = word.charAt(i) - 'a';
                int idx = node * 26 + c;
                if (child[idx] == 0) child[idx] = nodeCount++;
                node = child[idx];
            }
            terminal[node] = true;
        }

        for (String word : dict) {
            int[] nodes = new int[26];
            boolean[] used = new boolean[26];
            int count = 1;
            nodes[0] = 0;
            used[0] = false;

            for (int p = 0; p < word.length(); p++) {
                int[] nextNodes = new int[26];
                boolean[] nextUsed = new boolean[26];
                int nextCount = 0;
                int c = word.charAt(p) - 'a';

                for (int s = 0; s < count; s++) {
                    int node = nodes[s];
                    if (used[s]) {
                        int nxt = child[node * 26 + c];
                        if (nxt != 0) {
                            nextNodes[nextCount] = nxt;
                            nextUsed[nextCount++] = true;
                        }
                    } else {
                        int nxt = child[node * 26 + c];
                        if (nxt != 0) {
                            nextNodes[nextCount] = nxt;
                            nextUsed[nextCount++] = false;
                        }
                        for (int k = 0; k < 26; k++) {
                            if (k == c) continue;
                            int other = child[node * 26 + k];
                            if (other != 0) {
                                nextNodes[nextCount] = other;
                                nextUsed[nextCount++] = true;
                            }
                        }
                    }
                }

                nodes = nextNodes;
                used = nextUsed;
                count = nextCount;
                if (count == 0) break;
            }

            for (int s = 0; s < count; s++) {
                if (used[s] && terminal[nodes[s]]) return true;
            }
        }
        return false;
    }
}

