#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool differByOne(vector<string>& dict) {
        int total = 0;
        for (const string& word : dict) total += (int)word.size();
        int maxNodes = total + 1;
        vector<array<int, 26>> child(maxNodes);
        for (auto& row : child) row.fill(0);
        vector<char> terminal(maxNodes, 0);
        int nodeCount = 1;

        for (const string& word : dict) {
            int node = 0;
            for (char ch : word) {
                int c = ch - 'a';
                if (child[node][c] == 0) child[node][c] = nodeCount++;
                node = child[node][c];
            }
            terminal[node] = 1;
        }

        for (const string& word : dict) {
            vector<pair<int, bool>> states{{0, false}};
            for (char ch : word) {
                vector<pair<int, bool>> next;
                next.reserve(26);
                for (auto [node, used] : states) {
                    int c = ch - 'a';
                    if (used) {
                        int nxt = child[node][c];
                        if (nxt) next.push_back({nxt, true});
                    } else {
                        int nxt = child[node][c];
                        if (nxt) next.push_back({nxt, false});
                        for (int k = 0; k < 26; ++k) {
                            if (k == c || child[node][k] == 0) continue;
                            next.push_back({child[node][k], true});
                        }
                    }
                }
                states.swap(next);
                if (states.empty()) break;
            }
            for (auto [node, used] : states) {
                if (used && terminal[node]) return true;
            }
        }
        return false;
    }
};

