    for (const word of dict) {
        let states = [[0, false]];
        for (let p = 0; p < word.length; p++) {
            const next = [];
            const c = word.charCodeAt(p) - 97;
            for (const [node, used] of states) {
                if (used) {
                    const nxt = child[node * 26 + c];
                    if (nxt !== 0) next.push([nxt, true]);
                } else {
                    const same = child[node * 26 + c];
                    if (same !== 0) next.push([same, false]);
                    const base = node * 26;
                    for (let k = 0; k < 26; k++) {
                        if (k === c) continue;
                        const other = child[base + k];
                        if (other !== 0) next.push([other, true]);
                    }
                }
            }
            states = next;
            if (states.length === 0) break;
        }
        for (const [node, used] of states) {
            if (used && terminal[node]) return true;
        }
    }
    return false;
