#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

typedef struct {
    int child[26];
} Node;

static bool differByOne(char **dict, int dictSize) {
    int total = 0;
    for (int i = 0; i < dictSize; ++i) total += (int)strlen(dict[i]);

    int maxNodes = total + 1;
    Node *nodes = (Node *)calloc((size_t)maxNodes, sizeof(Node));
    unsigned char *terminal = (unsigned char *)calloc((size_t)maxNodes, sizeof(unsigned char));
    if (!nodes || !terminal) { free(nodes); free(terminal); return false; }

    int nodeCount = 1;
    for (int i = 0; i < dictSize; ++i) {
        int node = 0;
        for (const char *p = dict[i]; *p; ++p) {
            int c = *p - 'a';
            if (nodes[node].child[c] == 0) {
                nodes[node].child[c] = nodeCount++;
            }
            node = nodes[node].child[c];
        }
        terminal[node] = 1;
    }

    for (int w = 0; w < dictSize; ++w) {
        int curNode[26], nextNode[26];
        unsigned char curUsed[26], nextUsed[26];
        int curCount = 1;
        curNode[0] = 0;
        curUsed[0] = 0;

        const char *word = dict[w];
        int len = (int)strlen(word);
        for (int p = 0; p < len; ++p) {
            int nextCount = 0;
            int c = word[p] - 'a';
            for (int s = 0; s < curCount; ++s) {
                int node = curNode[s];
                if (curUsed[s]) {
                    int nxt = nodes[node].child[c];
                    if (nxt) {
                        nextNode[nextCount] = nxt;
                        nextUsed[nextCount++] = 1;
                    }
                } else {
                    int same = nodes[node].child[c];
                    if (same) {
                        nextNode[nextCount] = same;
                        nextUsed[nextCount++] = 0;
                    }
                    for (int k = 0; k < 26; ++k) {
                        if (k == c) continue;
                        int other = nodes[node].child[k];
                        if (other) {
                            nextNode[nextCount] = other;
                            nextUsed[nextCount++] = 1;
                        }
                    }
                }
            }
            memcpy(curNode, nextNode, (size_t)nextCount * sizeof(int));
            memcpy(curUsed, nextUsed, (size_t)nextCount * sizeof(unsigned char));
            curCount = nextCount;
            if (curCount == 0) break;
        }

        for (int s = 0; s < curCount; ++s) {
            if (curUsed[s] && terminal[curNode[s]]) {
                for (int i = 0; i < dictSize; ++i) free(dict[i]);
                free(dict);
                free(nodes);
                free(terminal);
                return true;
            }
        }
    }

    free(nodes);
    free(terminal);
    return false;
}

